            "content": "• 인간-기계 시스템의 3분류:\n  1) 수동 시스템: 인간이 수공구 등을 사용하여 직접 동력원이 되어 작업 수행\n  2) 기계화(반자동) 시스템: 동력은 기계가 제공하고, 인간은 조종장치로 제어 수행 (운전 등)\n  3) 자동 시스템: 기계가 감지·정보처리·제어·동력을 모두 수행하고 인간은 감시·유지보수 수행\n• 휴먼 에러(Swain 분류):\n  - 생략 오류 (Omission Error): 필요한 작업 단계나 절차를 빠뜨리고 수행하지 않은 오류\n  - 작위 오류 (Commission Error): 필요한 작업을 수행했으나 잘못된 방법·선택으로 수행한 오류\n  - 순서 오류 (Sequential Error): 작업의 순서를 뒤바꾸어 수행한 오류\n  - 시간 오류 (Time Error): 정해진 시간보다 너무 빠르거나 늦게 수행한 오류\n  - 과잉 행동 오류 (Extraneous Error): 불필요한 동작을 추가로 수행한 오류"
