            "content": "• 양립성의 4대 분류 (인간의 기대 모형과 기계 작동의 일치성):\n  1) 공간적 양립성: 물리적 배치의 일치 (예: 우측 스위치 ➡️ 우측 가스버너 점화)\n  2) 운동적 양립성: 조작 방향과 지시계 이동 방향의 일치 (예: 볼륨 노브를 시계방향 회전 ➡️ 음량 및 눈금 우측 증가)\n  3) 개념적 양립성: 문화적·고정관념적 연상의 일치 (예: 적색=위험·정지·온수, 청색/녹색=안전·정상·냉수)\n  4) 양식(감각) 양립성: 자극 양식과 반응 양식의 최적 결합 (예: 청각 자극 ➡️ 음성 반응)\n• 조종-반응비 (C/R비, Control-Response Ratio):\n  - 정의: C/R비 = (조종장치의 변위량) / (표시계기의 이동량)\n  - 정밀 조정 시 C/R비는 크게(민감도 낮게), 신속 이동 시 C/R비는 작게(민감도 높게) 설계하며 두 시간의 교차점이 최적 C/R비.\n• 시각표시장치 vs 청각표시장치 선택 기준:\n  - 청각장치가 유리할 때: 전언이 짧고 단순할 때, 즉각적 행동이 요구될 때, 직무상 수신자가 자주 움직일 때, 작업장이 너무 어둡거나 밝을 때."
