            "title": "4. 시스템 신뢰도(Reliability) 및 고장률(욕조곡선) 계산",
            "content": "• 고장률(λ)과 평균고장간격(MTBF) 및 신뢰도 R(t):\n  - 평균고장간격 MTBF = 1 / λ  (단, λ는 시간당 고장률)\n  - 지수분포 신뢰도: R(t) = e^(-λt)\n• 시스템 결합 방식별 신뢰도 공식:\n  1) 직렬 결합 (Series): R_s = R1 × R2 × ... × Rn\n     - 부품이 하나만 고장 나도 전체 고장. 부품 수가 증가할수록 전체 신뢰도는 가장 낮은 부품보다도 더 낮아짐!\n  2) 병렬 결합 (Parallel, 여분 시스템): R_p = 1 - (1 - R1)(1 - R2)...(1 - Rn)\n     - 모든 부품이 동시에 고장 나야 전체 고장. 부품 수가 증가할수록 전체 신뢰도 상승!\n• 욕조곡선 (Bathtub Curve) 고장 형태 3단계:\n  - 초기고장기간 (설계·제작 결함, 고장률 감소형 DFR ➡️ 번인·디버깅으로 예방)\n  - 우발고장기간 (사용 중 확률적 고장, 고장률 일정형 CFR ➡️ 안전여유 및 신뢰도 계산 구간)\n  - 마모고장기간 (부품 노후·열화, 고장률 증가형 IFR ➡️ 예방보전 PM으로 교체)"
