            "title": "5. 결함수 분석법 (FTA: Fault Tree Analysis) 완벽 정리",
            "content": "• FTA의 특징: Top-Down(하향식) 연역적 기법, 논리 기호를 이용한 도식화, 정성적·정량적 분석 모두 가능.\n• 주요 사상 및 게이트 기호:\n  - 직사각형: 중간사상 또는 정점사상(Top Event, 게이트의 출력 사상)\n  - 원(○): 기본사상(Basic Event, 더 이상 분해할 필요 없는 부품 자체의 고장)\n  - 마름모(◇): 생략사상(정보 부족 등으로 더 이상 전개하지 않는 사상)\n  - 집 모양(오각형): 통상사상(정상적으로 발생하는 사상)\n  - AND 게이트: 모든 입력이 동시에 발생할 때만 출력 발생 (곱집합: P = P1 × P2)\n  - OR 게이트: 입력 중 어느 하나라도 발생하면 출력 발생 (합집합: P = 1 - (1-P1)(1-P2) ≈ P1 + P2)\n• 컷셋(Cut Set) vs 패스셋(Path Set):\n  - 최소 컷셋 (Minimal Cut Set): 정점사상(사고)을 발생시키는 최소한의 기본사상들의 모임 (시스템의 위험성을 나타냄, 개수와 크기가 작을수록 안전)\n  - 최소 패스셋 (Minimal Path Set): 정점사상이 일어나지 않게(고장 예방) 하는 최소한의 기본사상들의 모임 (시스템의 안전성을 나타냄)"
