            "title": "6. 위험성 평가 기법 비교 (PHA, FMEA, HAZOP, ETA, THERP, MORT)",
            "content": "• PHA (예비위험분석): 시스템 개발·구상 초기 단계에서 위험요소를 식별하는 최초의 정성적 분석. (위험등급 4단계: 파국적 I - 위기적 II - 한계적 III - 무시가능 IV)\n• FMEA (고장형태 및 영향분석): 귀납적(Bottom-Up) 정성적 기법. 개별 부품의 고장 형태가 전체 시스템에 미치는 영향을 분석. (치명도 CA를 추가하면 FMECA)\n• HAZOP (위험 및 운전성 분석): 화학공장 배관·공정 설계도(P&ID)를 바탕으로 가이드워드(No, More, Less, As well as, Part of, Reverse, Other than)를 조합해 이탈 원인을 찾는 기법.\n• ETA (사건수 분석): 귀납적(Bottom-Up) 기법. 초기사상(Initiating Event)으로부터 안전장치의 작동 성공/실패 경로를 두 갈래로 추적.\n• THERP (인간과오율 예측기법): 인간의 작업 신뢰도를 정량적으로 평가하는 대표 기법.\n• MORT (경영소홀 및 위험나무): 관리·경영적 측면의 결함을 논리적으로 추적하는 기법."
