            "title": "1. 기계설비의 6대 위험점 (매회 2~3문항 필수 출제)",
            "content": "• 협착점 (Squeeze Point): 왕복운동을 하는 동작부분과 움직임이 없는 고정부분 사이에 형성 (예: 프레스의 슬라이드와 금형 베드, 사출성형기)\n• 끼임점 (Shear/Pinch Point): 고정부분과 회전운동 부분 사이에 형성 (예: 연삭숫돌과 워크레스트 사이, 선반의 바이트와 회전 공작물)\n• 물림점 (Nip Point): 서로 반대 방향으로 맞물려 회전하는 두 회전체 사이에 형성 (예: 기어와 기어, 롤러기와 롤러)\n• 절단점 (Cutting Point): 회전하는 톱날이나 왕복하는 칼날 자체에 의해 베이는 위험점 (예: 목재가공용 둥근톱, 띠톱, 밀링커터, 전단기 칼날)\n• 접선물림점 (Tangential Point): 회전하는 부분의 접선 방향으로 물려 들어가는 위험점 (예: 풀리와 V벨트, 스프로킷과 체인, 랙과 피니언)\n• 회전말림점 (Entanglement Point): 회전하는 축이나 돌기물에 작업복·머리카락·장갑이 감겨 들어가는 위험점 (예: 드릴, 리머, 커플링 볼트, 교반기 날개)"
