            "title": "2. 프레스 및 전단기 방호장치와 안전거리 계산 공식 [초빈출]",
            "content": "• 급정지 기구가 있는 프레스(마찰클러치)에만 사용 가능한 방호장치: 광전자식(감응식), 양수조작식(안전1행정용)\n• 급정지 기구가 없는 프레스(확동클러치)에도 사용 가능한 방호장치: 게이트가드식, 손쳐내기식, 수인식\n• 안전거리(D) 계산 공식:\n  1) 광전자식 방호장치: D = 1.6 × (T_l + T_s) [mm]\n     - 1.6: 손의 이동속도 (1.6 m/s = 1,600 mm/s)\n     - T_l + T_s: 광선 차단 시점부터 급정지 기구가 작동하여 슬라이드가 정지할 때까지의 총 시간 [ms]\n  2) 양수조작식 방호장치 (급정지 프레스): D = 1.6 × T_m [mm]\n     - T_m: 누름버튼에서 손을 뗀 때부터 급정지할 때까지의 최대 정지시간 [ms]\n  3) 양수조작식 안전장치 (클러치 맞물림 개소수 N, 회전수 SPM):\n     - D = 1.6 × (1/2 + 1/N) × (60,000 / SPM) [mm]\n• 손쳐내기식 및 수인식 적용 조건: 행정길이 40mm 이상(수인식은 볼스터 전후 120mm 이상), 매분 행정수(SPM) 120 이하인 프레스."
