            "content": "• 롤러기 급정지장치:\n  - 조작부 설치 위치(밑면 기준): 손 조작식(1.8m 이내), 복부 조작식(0.8m 이상 1.1m 이내), 무릎 조작식(0.4m 이상 0.6m 이내)\n  - 급정지거리: 앞면 롤러 표면속도가 30m/min 미만일 때 [앞면 롤러 원주의 1/3 이내], 30m/min 이상일 때 [앞면 롤러 원주의 1/2.5 이내]\n• 연삭기(그라인더) 안전기준:\n  - 숫돌과 워크레스트(받침대) 간격: 3mm 이하 (자주 나오는 안전수칙: 2~3mm 이내 유지)\n  - 숫돌과 덮개 조정편(가드 혀) 간격: 3mm ~ 10mm 이내\n  - 작업 시작 전 시험운전: 매일 작업 시작 전 1분 이상, 숫돌 교체 후에는 3분 이상 시운전!\n  - 덮개 노출 각도: 일반 원통연삭 90° 이내, 워크레스트 사용 평면연삭 125° 이내(수평면 위 65°), 상부 사용 연삭 60° 이내\n• 목재가공용 둥근톱:\n  - 방호장치 2종: 톱날접촉예방장치(덮개) + 반발예방장치(분할날 등)\n  - 분할날(Riving Knife) 기준: 톱날 두께의 1.1배 이상, 톱날 뒷면과의 간격 12mm 이내, 표준 테이블면 위 톱날 높이의 2/3 이상 덮을 것."
