            "title": "3. 정전기 재해 메커니즘 및 4대 예방 대책",
            "content": "• 정전기 발생 특징: 전압은 수천~수만 V로 매우 높으나 전류(전하량)가 작아 감전사보다는 '인체에 의한 2차 추락사고'나 '가연성 가스·분진의 방전 스파크 착화원(화재·폭발)'으로 매우 위험함.\n  - 가연성 증기 최소착화에너지(MIE): 약 0.2 ~ 0.25 mJ (정전기 스파크 에너지 10~20mJ로 쉽게 폭발)\n• 정전기 발생에 영향을 주는 요인:\n  - 물체의 분리 속도가 빠를수록, 접촉 면적이 넓고 압력이 클수록, 상대습도가 낮을수록(건조할수록) 많이 발생.\n• 정전기 재해 예방 4대 대책:\n  1) 접지(Earthing): 도체에 축적된 전하를 대지로 방출 (접지저항 10⁶ Ω 이하)\n  2) 가습(습도 조절): 작업장 상대습도를 70% 이상(65~75%)으로 유지하여 부도체 표면에 수분막 형성\n  3) 제전기 사용: 부도체(플라스틱, 필름, 섬유)는 접지만으로 제거 불가 ➡️ 전압인가식·자기방전식·방사선식 제전기로 공기 이온화 중화\n  4) 도전성 재료 사용 및 유속 제한(배관 내 비전도성 액체 유속 1 m/s 이하 제한), 제전복·제전화 착용."
