            "title": "4. 폭발위험장소 구분 및 전기 방폭구조 기호 [매회 출제]",
            "content": "• 가스·증기 폭발위험장소 3종 구분:\n  - 0종 장소: 폭발성 분위기가 연속적 또는 장시간 존재하는 장소 (탱크·용기 내부) ➡️ 본질안전 방폭구조(ia)만 사용 가능!\n  - 1종 장소: 정상 작동 중 폭발성 분위기가 생성될 가능성이 있는 장소 (맨홀·밸브 주변)\n  - 2종 장소: 이상 상태에서 단시간만 폭발성 분위기가 존재할 우려가 있는 장소\n• 분진 폭발위험장소 3종 구분: 20종 장소(연속) - 21종 장소(정상 시 가끔) - 22종 장소(비정상 시 단시간)\n• 전기기계·기구 방폭구조 기호 암기:\n  - 내압(耐壓) 방폭구조 [d]: 내부 폭발 시 용기가 압력에 견디고 접합면 틈새를 통해 외부 화염 전파 차단.\n  - 압력 방폭구조 [p]: 용기 내부에 보호가스(질소·공기)를 압입해 양압(+)을 유지하여 외부 가스 침입 차단.\n  - 유입 방폭구조 [o]: 불꽃 발생 부위를 절연유 속에 침전시켜 가스와 격리.\n  - 안전증 방폭구조 [e]: 정상 운전 중 불꽃·고온이 발생하지 않는 기기(유도전동기, 단자함 등)의 절연·온도상승 안전도를 한층 강화.\n  - 본질안전 방폭구조 [ia, ib]: 정상 및 사고 시 발생하는 전기불꽃 에너지를 최소착화에너지 이하로 억제 (계측기·센서 회로)."
