            "content": "• 토질시험의 종류:\n  - 표준관입시험 (SPT, N치 측정): 사질토(모래지반)의 상대밀도와 지지력 추정에 가장 적합. (63.5kg 해머를 76cm 낙하시켜 30cm 관입 타격횟수 N)\n  - 베인테스트 (Vane Test): 연약한 점성토(점토지반)의 현장 전단강도(점착력) 측정.\n• 굴착공사 흙막이 바닥 붕괴 3대 현상 [무조건 구분 암기]:\n  1) 히빙 (Heaving, 연약 점토지반): 굴착 배면의 흙 무게(토압)가 굴착 바닥면의 지지력보다 커서 흙막이 바깥 흙이 안으로 밀려 들어오며 굴착 바닥면이 부풀어 오르는 현상.\n  2) 보일링 (Boiling, 사질토/모래지반): 지하수위가 높은 모래지반에서 굴착 바닥면과 배면의 수두차에 의해 지하수가 모래와 함께 끓어오르듯 분출하여 지지력을 잃는 현상.\n  3) 파이핑 (Piping): 흙막이 벽체의 부실 시공 구멍이나 이음부를 통해 물길이 형성되어 토사가 유출되는 현상.\n  ★ 방지대책 공통: 흙막이 벽의 근입깊이(박는 깊이)를 깊게 함, 웰포인트 공법 등으로 지하수위 저하, 지반 개량(약액주입)."
