            "content": "• 강관비계(단관비계) 조립 기준:\n  - 비계기둥 간격: 띠장 방향 1.85 m 이하, 장선(간사이) 방향 1.5 m 이하\n  - 첫 번째 띠장 높이: 지상으로부터 2 m 이하에 설치\n  - 비계기둥 최고부로부터 31m 되는 지점 밑부분의 기둥은 2개의 강관으로 묶어 세울 것\n  - 기둥 간 적재하중: 400 kg을 초과하지 않도록 할 것\n• 비계 종류별 벽이음(Tie) 조립 간격 (수직 : 수평):\n  - 단관비계(강관비계): 수직 5 m 이하, 수평 5 m 이하\n  - 틀비계(높이 5m 미만 제외): 수직 6 m 이하, 수평 8 m 이하\n  - 통나무비계: 수직 5.5 m 이하, 수평 7.5 m 이하\n• 거푸집 동바리 (파이프 서포트) 조립 기준:\n  - 파이프 서포트를 3개 이상 이어서 사용하지 않도록 할 것\n  - 이어서 사용할 때는 4개 이상의 볼트 또는 전용 철물을 사용하여 이을 것\n  - 높이가 3.5 m를 초과할 경우에는 높이 2 m 이내마다 수평연결재를 2개 방향으로 만들고 변위를 방지할 것."
